import java.sql.*;
import java.util.logging.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_ID = Pattern.compile("^[A-Za-z0-9_-]{1,64}$");

    // Connection pool configured via JNDI
    private Connection getConnection() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportDB");
        return ds.getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String sortCol = req.getParameter("sort");

        if (reportId == null || !SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Format validation - only allow known formats
        if (format != null && !format.matches("^(csv|json|xml)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Sort column - used in ORDER BY clause
        // Developer note: validated against allowlist in production config
        String orderClause = "";
        if (sortCol != null && !sortCol.isEmpty()) {
            // Basic length check to prevent obvious abuse
            if (sortCol.length() > 128) {
                resp.sendError(400, "Sort parameter too long");
                return;
            }
            orderClause = " ORDER BY " + sortCol;
        }

        String baseQuery = "SELECT r.id, r.title, r.created_at, r.status, r.owner_id " +
                          "FROM reports r WHERE r.report_id = ?" + orderClause;

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(baseQuery)) {

            ps.setString(1, reportId);

            try (ResultSet rs = ps.executeQuery()) {
                resp.setContentType("application/json");
                PrintWriter out = resp.getWriter();
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    first = false;
                    out.printf("  {\"id\": %d, \"title\": \"%s\", \"created\": \"%s\", \"status\": \"%s\"}",
                        rs.getInt(1),
                        escapeJson(rs.getString(2)),
                        rs.getTimestamp(3).toString(),
                        escapeJson(rs.getString(4)));
                }
                out.print("\n]");
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } catch (Exception e) {
            log.severe("Unexpected error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Audit log endpoint - logs report access for compliance
        String userId = req.getHeader("X-Authenticated-User");
        String action = req.getParameter("action");
        String target = req.getParameter("target");

        if (userId == null || action == null) {
            resp.sendError(400);
            return;
        }

        // Insert audit record - fully parameterized
        String auditSql = "INSERT INTO audit_log (user_id, action, target_id, ts) VALUES (?, ?, ?, NOW())";
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(auditSql)) {
            ps.setString(1, userId);
            ps.setString(2, action);
            ps.setString(3, target);
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (Exception e) {
            log.warning("Audit insert failed: " + e.getMessage());
            resp.sendError(500);
        }
    }
}
